SELECT EXISTS(SELECT 1 FROM (SELECT e.*,e.account_id AS owner FROM owned_calendar_events e)t WHERE t.id=$2 AND t.deleted_at IS NULL AND EXISTS(SELECT 1 FROM owned_authority_accounts a WHERE a.id=t.owner AND NOT a.disabled AND NOT EXISTS(SELECT 1 FROM owned_authority_punishments u WHERE u.account_id=a.id AND u.kind='disable_account' AND(u.starts_at IS NULL OR u.starts_at<=clock_timestamp())AND(u.expires_at IS NULL OR u.expires_at>clock_timestamp()))) AND NOT EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.status=-100 AND((b.account_id=t.owner AND b.related_id=NULLIF($1::text,'')::uuid)OR(b.related_id=t.owner AND b.account_id=NULLIF($1::text,'')::uuid))) AND(t.owner=NULLIF($1::text,'')::uuid OR t.visibility=200 OR(t.visibility=100 AND (EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.account_id=t.owner AND b.related_id=NULLIF($1::text,'')::uuid AND b.status>=100)AND EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.related_id=t.owner AND b.account_id=NULLIF($1::text,'')::uuid AND b.status>=100)))))
